package android.content;import java.util.*;public class ContentValues extends HashMap<String,Object> {public void put(String k,String v){super.put(k,v);}public void put(String k,Integer v){super.put(k,v);}public void put(String k,Long v){super.put(k,v);}public Integer getAsInteger(String k){return (Integer)get(k);}public String getAsString(String k){Object o=get(k);return o==null?null:o.toString();}}
